"use client";

import { useCallback, useEffect, useState } from "react";
import type { StudyDocument } from "@/types";
import { deleteDocument, getDocuments } from "@/services/api";
import { useToast } from "@/components/ui/Toast";

export function useDocuments() {
  const [documents, setDocuments] = useState<StudyDocument[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const toast = useToast();

  const refresh = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const docs = await getDocuments();
      setDocuments(docs);
    } catch {
      setError("Couldn't load your documents. Try again.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const remove = useCallback(
    async (id: string) => {
      const prev = documents;
      setDocuments((docs) => docs.filter((d) => d.id !== id));
      try {
        await deleteDocument(id);
        toast.success("Document deleted");
      } catch {
        setDocuments(prev);
        toast.error("Couldn't delete that document");
      }
    },
    [documents, toast]
  );

  const addDocument = useCallback((doc: StudyDocument) => {
    setDocuments((docs) => [doc, ...docs]);
  }, []);

  return { documents, isLoading, error, refresh, remove, addDocument };
}
